import{_ as e,o,c as d,a2 as a}from"./chunks/framework.DGk0zlJw.js";const u=JSON.parse('{"title":"商店提交前置清单","description":"","frontmatter":{},"headers":[],"relativePath":"zh/store-submission.md","filePath":"zh/store-submission.md"}'),i={name:"zh/store-submission.md"};function c(s,t,r,n,l,p){return o(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="商店提交前置清单" tabindex="-1">商店提交前置清单 <a class="header-anchor" href="#商店提交前置清单" aria-label="Permalink to &quot;商店提交前置清单&quot;">​</a></h1><p>Beacon 本体仍是 <strong>unpackaged 自包含</strong>（RFC §10，<code>WindowsPackageType=None</code>）——商店提交只是多产一个 MSIX 包，把 publish 输出整体包起来，包内 Identity 给商店识别用；应用运行形态不变。本页记三件事：MSIX 怎么产、隐私政策页要什么字段、商店素材要备什么。</p><h2 id="状态-2026-10-12" tabindex="-1">状态（2026-10-12） <a class="header-anchor" href="#状态-2026-10-12" aria-label="Permalink to &quot;状态（2026-10-12）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>状态</th></tr></thead><tbody><tr><td>SignPath 免费签名</td><td><strong>参数已接真</strong>（2026-10-12）：<code>api-token</code> 与 <code>organization-id</code> 走仓库 Secrets（<code>SIGNPATH_API_TOKEN</code> / <code>SIGNPATH_ORGANIZATION_ID</code>，不硬编码），<code>project-slug: beacon</code>、<code>signing-policy-slug: beacon</code>；<code>artifact-configuration-slug</code> 为可选参数，省略 = 用项目默认 Artifact Configuration（用户在控制台建 Portable Executable + deep signing 配置后如需指定可再填）。<strong>剩用户侧一步（不由 agent 代做）</strong>：在 SignPath 控制台把 API token 所属用户加进 signing policy「beacon」的 <strong>Submitters</strong> 列表——做完后下一次 <code>v*</code> tag 起自动签名；未做前版本 tag 构建会在签名步红（fail closed，不静默发未签名正式版）。政策见 README「代码签名政策」</td></tr><tr><td>MSIX 打包</td><td><strong>已在 Windows runner 验证通过并字节级验包</strong>（2026-10-12 两轮 dry run 全绿，包内 manifest 版本替换实测发生）：MakeAppx 就位、清单被接受、约 66 MB 包产出。打包逻辑与 nightly 版本 tag 通道共用 <code>.github/workflows/scripts/msix-pack.ps1</code></td></tr><tr><td>商店应用预留</td><td>未开始。Partner Center 预留应用名后才确定 <code>appxmanifest</code> 的 <code>Identity Name</code> / <code>Publisher</code></td></tr><tr><td>隐私政策页</td><td><strong>已就绪</strong>：<a href="https://cuihairu.github.io/beacon/privacy-policy/" target="_blank" rel="noreferrer">https://cuihairu.github.io/beacon/privacy-policy/</a>（<code>docs/privacy-policy.md</code>，随 docs 工作流发布；字段对照见第 1 节）</td></tr><tr><td>商店素材</td><td>图标已备；截图 / 说明 / 分类 / 分级问卷未备（见第 2 节）</td></tr></tbody></table><h2 id="_1-隐私政策页必填字段" tabindex="-1">1. 隐私政策页必填字段 <a class="header-anchor" href="#_1-隐私政策页必填字段" aria-label="Permalink to &quot;1. 隐私政策页必填字段&quot;">​</a></h2><p>商店规则：应用访问个人数据或具备网络访问能力时，必须提供<strong>公开可访问</strong>的隐私政策 URL。Beacon 有网络访问（GitHub API + 各 AI 平台用量端点）且在本地保存 API token，属必填项。</p><p>页面至少写清这些字段（左列是字段，右列是 Beacon 的实际答案，可直接抄）：</p><table tabindex="0"><thead><tr><th>字段</th><th>Beacon 的实际答案</th></tr></thead><tbody><tr><td>收集哪些数据</td><td>API token（GitHub PAT、各 AI 平台 key）；用户配置（连接、刷新间隔、主题、组件布局）；本机状态读数（CPU / 内存 / 磁盘 / 网络速率 / IP）</td></tr><tr><td>数据存在哪</td><td>全部本地：token 写 DPAPI 密钥库，配置写 <code>%AppData%\\Beacon\\config.json</code>（仅存 credentialRef，<strong>绝无明文 token</strong>），日志写 <code>%AppData%\\Beacon\\logs</code></td></tr><tr><td>数据如何离开本机</td><td>只发给用户自己配置的 API 端点（GitHub API、各 AI 平台控制台/用量端点）；不发给任何第三方，无遥测上报</td></tr><tr><td>数据用途</td><td>仅本地展示状态与执行本地操作；token 只用于向对应平台鉴权查询</td></tr><tr><td>保留与删除</td><td>随安装目录删除；卸载走系统「添加或删除程序」；无云端副本</td></tr><tr><td>联系方式</td><td>待填（邮箱或 GitHub profile）</td></tr></tbody></table><p>落地要求：</p><ul><li>[x] 公开 URL 已就绪：<code>https://cuihairu.github.io/beacon/privacy-policy/</code>（<code>docs/privacy-policy.md</code>，docs 工作流发布，提交页直接填它）</li><li>[ ] 提交前该 URL 必须已可访问（商店会抓取）</li><li>[ ] 不能是 <code>localhost</code> / 内网地址 / 需登录才能看的页面</li></ul><h2 id="_2-商店素材清单" tabindex="-1">2. 商店素材清单 <a class="header-anchor" href="#_2-商店素材清单" aria-label="Permalink to &quot;2. 商店素材清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>要求</th><th>Beacon 现状</th></tr></thead><tbody><tr><td>应用图标</td><td>310x310 PNG；manifest 内 <code>Logo</code>（商店列表小图标）用 50x50</td><td>已备：<code>packaging/msix/Square310x310Logo.png</code>、<code>StoreLogo.png</code>（由 <code>docs/img/logo.svg</code> 光栅化，同批还有 44/71/150/310x150 供包内磁贴用）</td></tr><tr><td>截图</td><td>至少 1 张，建议 4 张以上；PNG 或 JPG；常见尺寸 1920x1080（也接受 1366x768 / 2560x1440）；单文件大小上限按提交页提示</td><td>未备。可从 <code>docs/img/evidence/</code> 现有取证截图里选底，但那些多为暗色主题特写，需补浅色主题 + 多屏 + 设置页</td></tr><tr><td>应用说明</td><td>最多 10000 字符；写产品定位 / 功能点 / 支持场景，可含关键词</td><td>未备。可复用 README 的安装段 + <code>docs/mission.md</code> 的定位段改写</td></tr><tr><td>分类</td><td>主分类 + 次分类，从商店分类列表里选（开发者工具 / 效率是候选）</td><td>未拍板</td></tr><tr><td>年龄分级问卷</td><td>IARC 问卷逐项答：暴力、恐怖或惊悚、粗俗语言、烟酒、色情或裸露、用户交互、应用内购买</td><td>未答。Beacon 无内容风险项，预期结果为「Everyone」</td></tr><tr><td>支持 URL</td><td>需填（GitHub issues 即可）</td><td>未拍板</td></tr></tbody></table><blockquote><p>具体尺寸上限、可选分类值与问卷措辞以提交时 Partner Center 页面为准——本表的数字是常见口径，提交前对照一次。</p></blockquote><h2 id="_3-msix-打包-卡点与替代方案" tabindex="-1">3. MSIX 打包：卡点与替代方案 <a class="header-anchor" href="#_3-msix-打包-卡点与替代方案" aria-label="Permalink to &quot;3. MSIX 打包：卡点与替代方案&quot;">​</a></h2><p>打包链路（<code>.github/workflows/nightly.yml</code>，仅 <code>v*</code> tag 通道）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>publish/（自包含输出）+ packaging/msix/appxmanifest.xml（版本按 tag 替换）</span></span>
<span class="line"><span>  → 暂存目录 AppxManifest.xml + publish 全部文件</span></span>
<span class="line"><span>  → makeappx pack /d &lt;暂存&gt; /p &lt;asset&gt;.msix</span></span>
<span class="line"><span>  → 进 SHA256SUMS + gh release upload</span></span></code></pre></div><ul><li><strong>版本对齐</strong>：manifest 里 <code>Version=&quot;0.0.0.0&quot;</code> 是占位，工作流按 <code>v*</code> tag 四段化替换（<code>v0.1.3</code> → <code>0.1.3.0</code>）；exe 自身的 <code>Version</code> 由 publish 步骤注入同一 tag 版本，两者恒等。</li><li><strong>未签名 MSIX 是有意为之</strong>：商店提交阶段由 Microsoft 代签，本地不签。sideload 测试需自备开发证书（<code>makeappx pack /o</code> + 自签证书），属提交前的本地验证步骤，不在 CI 里做。</li><li><strong>提交前必须替换的占位</strong>：<code>Identity Name=&quot;Beacon.CuiHairu&quot;</code> → Partner Center 预留的应用名；<code>Publisher=&quot;CN=cuihairu&quot;</code> → 提交证书主题（与 <code>PublisherDisplayName</code> 一致）。</li><li><strong>Windows runner 实测（2026-10-12，两轮 dry run 全绿：38230149697 + 38233094172）</strong>： <ul><li>MakeAppx 在 runner 上就位：<code>C:\\Program Files (x86)\\Windows Kits\\10\\bin\\10.0.26100.0\\x86\\makeappx.exe</code></li><li>手写清单被 MakeAppx 接受（命名空间 / <code>uap:VisualElements</code> / <code>uap:DefaultTile</code> / <code>rescap:runFullTrust</code> 全部有效），打包约 10s 完成</li><li>包级字节验证（产物下载回本地解包）：zip 容器有效，约 66 MB / 502 条目；<code>AppxManifest.xml</code> + 6 张 Logo 全在包根且字节数与仓库文件逐一吻合；<code>Beacon.App.exe</code> 与 <code>Assets\\</code> 随 publish 进包</li><li>版本替换路径实测（run 38233094172，试跑台故意传 9.9.9.9 ≠ 占位）：包内 Identity 实际变为 <code>Version=&quot;9.9.9.9&quot;</code>、占位 <code>0.0.0.0</code> 消失——「版本与 v* tag 对齐」机制被证明真实发生，不是空替换</li></ul></li><li><strong>当时唯一的卡点是「没法试跑」</strong>：MSIX 步骤只在 <code>v*</code> tag 通道跑，而版本 tag 由作者手动给出（仓库红线：不打 tag），用已有 tag 试跑会往已发布 release 上传别的 commit 的资产，属交付完整性违规。解法是抽共享脚本 <code>.github/workflows/scripts/msix-pack.ps1</code> + 只建包不碰 release/tag 的 <code>.github/workflows/msix-dry-run.yml</code> 试跑台。</li></ul><p>如果打包链路将来出问题，替代方案（按推荐顺序）：</p><ol><li><strong>Sparse 包</strong>（<code>WindowsPackageType=Sparse</code>）——WinUI 3 官方支持的「有包标识但仍按 unpackaged 运行」模式：csproj 加 <code>WindowsPackageType=Sparse</code> + <code>PackageCertificateKeyFile</code>，appxmanifest 由 MSBuild 自动生成（不用手写）。代价：本地开发与便携形态要跟着换模式。</li><li><strong>App Installer 分发</strong>（<code>.appinstaller</code>）——不进商店的企业/个人分发通道。</li><li><strong>只发 zip + setup.exe</strong>——商店不是分发必需品：便携 zip + Inno Setup 安装包已覆盖个人分发，MSIX 仅为上架。</li></ol>`,19)])])}const h=e(i,[["render",c]]);export{u as __pageData,h as default};
